sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float blockSize;
uniform float2 stretch;
uniform float2 offset;
uniform float angle;
uniform float vignette;
uniform float screenSpace;
uniform float edges;
uniform float threshold;
uniform float saturation;
uniform float style;
uniform float edgeStyle;

half4 main(float2 coord) {
    float2 origin = (screenSpace > 0.5 ? screen.xy + screen.zw * 0.5 : size * 0.5) + offset;
    if (style > 0.5 && blockSize <= 0.0) return half4(0.0);
    float2 cell = max(blockSize * abs(stretch), float2(1.0));
    float a = radians(angle);
    float c = cos(a);
    float s = sin(a);
    float2 d = coord - origin;
    float2 p = float2(c * d.x + s * d.y, c * d.y - s * d.x) / cell;
    float2 b = floor(p);
    float2 m = (b + 0.5) * cell;
    float2 q = origin + float2(c * m.x - s * m.y, s * m.x + c * m.y);
    float slack = style > 0.5 ? 0.5 : 0.0;
    if (edgeStyle > 0.5) q = clamp(q, screen.xy + 0.5, screen.xy + screen.zw - 0.5);
    else if (edges > 0.5 && (q.x < -slack || q.y < -slack || q.x > size.x + slack || q.y > size.y + slack)) return half4(0.0);
    else if (style > 0.5) q = clamp(q, float2(0.5), size - 0.5);
    half4 col = image.eval(edgeStyle > 0.5 ? clamp(q, float2(0.5), size - 0.5) : q);
    if (edgeStyle > 0.5) {
        float2 w = clamp(q + 0.5, 0.0, 1.0) * clamp(size - q + 0.5, 0.0, 1.0);
        col *= half(w.x * w.y);
    }
    if (col.a < threshold) return half4(0.0);
    if (saturation > 0.5 && col.a > 0.0) col *= half(1.0 + (1.0 / float(col.a) - 1.0) * clamp(2.0 * saturation - 1.0, 0.0, 1.0));
    if (vignette > 0.0 && col.a > 0.001) {
        float2 e = abs(p - b - 0.5) * 2.0;
        half3 un = col.rgb / col.a;
        float t = vignette * (0.09 + 0.0117 * blockSize * dot(e * e, abs(stretch)));
        col.rgb = style > 0.5 ? max(un - half(t) * un * (1.0 - un), half3(0.0)) * col.a
                              : max(un - half(vignette * (0.04 + 0.08 * dot(e, e))), half3(0.0)) * col.a;
    }
    return col;
}
